import{_ as s,C as i,o as e,c,ac as t,b as n,w as o,a as l,E as d,ad as p}from"./chunks/framework.Bzw8ikz_.js";const _="/hubHooks/assets/%E4%BA%8B%E4%BB%B6%E5%BE%AA%E7%8E%AF.CFKDJK5s.png",b=JSON.parse('{"title":"基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"front/browser/事件循环.md","filePath":"front/browser/事件循环.md","lastUpdated":1773383624000}'),h={name:"front/browser/事件循环.md"};function m(u,a,E,B,k,A){const r=i("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><h2 id="执行栈-execution-stack" tabindex="-1">执行栈（Execution Stack） <a class="header-anchor" href="#执行栈-execution-stack" aria-label="Permalink to &quot;执行栈（Execution Stack）&quot;">​</a></h2><p>所有的代码都是在主线程上执行的。主线程维护着一个执行栈（Execution Stack，也叫调用栈 Call Stack），用于管理所有的同步任务</p><h2 id="宏任务-macrotask" tabindex="-1">宏任务（Macrotask）： <a class="header-anchor" href="#宏任务-macrotask" aria-label="Permalink to &quot;宏任务（Macrotask）：&quot;">​</a></h2><p>包括整体的 <code>script 代码</code>、<code>setTimeout</code>、<code>setInterval</code>、<code>I/O 操作</code>等</p><p>宏任务按照队列顺序执行，每次执行一个</p><h2 id="微任务-microtask" tabindex="-1">微任务（Microtask）： <a class="header-anchor" href="#微任务-microtask" aria-label="Permalink to &quot;微任务（Microtask）：&quot;">​</a></h2><p>包括 <code>Promise.then/catch/finally</code>、<code>process.nextTick（Node.js）</code>、<code>MutationObserver</code> 等</p><p>当同步任务，会立即执行所有微任务队列中的任务</p><h1 id="事件循环" tabindex="-1">事件循环 <a class="header-anchor" href="#事件循环" aria-label="Permalink to &quot;事件循环&quot;">​</a></h1><p>首先当一段代码进入执行栈中，会依次执行调用栈中的代码，先<strong>执行同步任务</strong>，再执行<strong>微任务</strong>，最后执行<strong>宏任务</strong>。 正儿八经的顺序是这样的，但是这里会有一个点，就是宏任务这里，每个宏任务执行完，会再去检查一下微任务中，有没有代码，如果有（可能是这个宏任务执行的时候产生了一个微任务），则优先去执行微任务。</p><p>执行顺序：</p>',12)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%90%8C%E6%AD%A5%E4%BB%BB%E5%8A%A1%5D%20--%3E%20B%5B%E5%BE%AE%E4%BB%BB%E5%8A%A1%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%AE%8F%E4%BB%BB%E5%8A%A1%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="图解" tabindex="-1">图解 <a class="header-anchor" href="#图解" aria-label="Permalink to &quot;图解&quot;">​</a></h2><p><img src="'+_+'" alt="事件循环"></p><p><strong>JavaScript 事件循环的核心特性</strong>：</p><ol><li>同步代码优先执行</li><li>每个宏任务执行完后，都会清空微任务队列</li><li>微任务队列清空后，才会执行下一个宏任务</li><li>Promise 的执行器（executor）是同步执行的，而 then 中的回调是异步的（微任务）</li><li>setTimeout 的回调是宏任务，会在下一轮事件循环中执行</li></ol>',4))])}const x=s(h,[["render",m]]);export{b as __pageData,x as default};
